pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address owner) public {
        vm.assume(owner != address(0));
        vm.assume(amount > 0 && amount <= address(this).balance + 1e30);
        vm.deal(owner, amount);
        // adversarial counterparty: a receiver that refuses any funds
        Reverter receiver = new Reverter();
        vm.prank(owner);
        bool ok;
        try c.sendTo{value: amount}(address(receiver), amount) {
            ok = true;
        } catch {
            ok = false;
        }
        // Rule: since the receiver refuses funds, sendTo must revert and no value may leave c.
        // Mutant: send's false return is unchecked, the call completes, funds stay in c and no revert occurs.
        assertTrue(!ok && address(c).balance == 0);
    }
}

